css:
:scope { width: min(100%, 1338px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 24; grid-row: 1 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.2em; text-transform: uppercase; color: var(--os-color-text); }
.gx__i2 { grid-column: 1 / span 24; grid-row: 5 / span 27; font-family: var(--os-font-heading); font-size: 128px; font-weight: 700; line-height: 0.84; letter-spacing: -0.035em; color: var(--os-color-text); }
.gx__i3 { grid-column: 1 / span 11; grid-row: 49 / span 11; font-family: var(--os-font-body); font-size: 23.4px; font-weight: 400; line-height: 1.25; letter-spacing: 0em; font-style: italic; color: var(--os-color-text); }
.gx__i4 { grid-column: 15 / span 9; grid-row: 59 / span 2; font-family: var(--os-font-label); font-size: 10px; font-weight: 700; line-height: 1.55; letter-spacing: 0.22em; text-transform: uppercase; color: var(--os-color-link); }
.gx__i5 { grid-column: 1 / span 3; grid-row: 63 / span 7; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.2em; text-transform: uppercase; color: var(--os-color-surface); }
.gx__i6 { grid-column: 4 / span 2; grid-row: 63 / span 7; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.2em; text-transform: uppercase; color: var(--os-color-text); }
.gx__i7 { grid-column: 15 / span 4; grid-row: 62 / span 2; font-family: var(--os-font-label); font-size: 10px; font-weight: 400; line-height: 1.55; letter-spacing: 0.16em; text-transform: uppercase; color: var(--os-color-text); }
.gx__i8 { grid-column: 20 / span 4; grid-row: 62 / span 2; font-family: var(--os-font-label); font-size: 10px; font-weight: 400; line-height: 1.55; letter-spacing: 0.16em; text-transform: uppercase; color: var(--os-color-text); }
.gx__i9 { grid-column: 15 / span 4; grid-row: 65 / span 2; font-family: var(--os-font-label); font-size: 10px; font-weight: 400; line-height: 1.55; letter-spacing: 0.16em; text-transform: uppercase; color: var(--os-color-text); }
.gx__i10 { grid-column: 20 / span 4; grid-row: 65 / span 2; font-family: var(--os-font-label); font-size: 10px; font-weight: 400; line-height: 1.55; letter-spacing: 0.16em; text-transform: uppercase; color: var(--os-color-text); }
.gx__i11 { grid-column: 15 / span 4; grid-row: 68 / span 2; font-family: var(--os-font-label); font-size: 10px; font-weight: 400; line-height: 1.55; letter-spacing: 0.16em; text-transform: uppercase; color: var(--os-color-text); }
.gx__i12 { grid-column: 22 / span 2; grid-row: 76 / span 2; font-family: var(--os-font-label); font-size: 10.6px; font-weight: 400; line-height: 1.55; letter-spacing: 0.14em; text-transform: uppercase; text-align: right; color: var(--os-color-link); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i2 { font-family: var(--os-font-heading); font-size: 102px; }
  .gx__i3 { font-family: var(--os-font-body); font-size: 19px; }
  .gx__i4 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i5 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i6 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i7 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i8 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i9 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i10 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i11 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i12 { font-family: var(--os-font-label); font-size: 14px; }
}
